import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    var firstLine = true

    while (scanner.hasNextLine()) {
        val str = scanner.nextLine()
        if (firstLine) {
            firstLine = false
            continue
        }

        var ans = 0
        val arr = str.split(" ")

        for (word in arr) {
            var curr = 0
            for (ch in word) {
                if (ch in 'A'..'Z') {
                    curr++
                }
            }
            ans = maxOf(ans, curr)
        }

        println(ans)
    }
}

